//! Auth: initData checked against vectors from an independent Node signer (`tests/fixtures/sign_initdata.mjs`).

use serde::Deserialize;
use server::auth::{InitData, InitDataError, data_check_string, validate_init_data};

use crate::common;

/// `tests/fixtures/initdata_vectors.json`, generated by `sign_initdata.mjs --write`.
#[derive(Deserialize)]
struct Vectors {
    bot_token: String,
    max_age_secs: i64,
    now: i64,
    vectors: Vec<Vector>,
}

#[derive(Deserialize)]
struct Vector {
    name: String,
    init_data: String,
    /// `ok`, or the `InitDataError` variant name.
    expect: String,
    /// The verified user an `ok` vector yields.
    #[serde(default)]
    user: Option<ExpectedUser>,
}

#[derive(Deserialize)]
struct ExpectedUser {
    id: i64,
    first_name: String,
    language_code: Option<String>,
}

/// Every vector the signer writes; `initdata_all_vectors_match_expectations` checks the file holds exactly these.
const VECTOR_COUNT: usize = 24;

fn vectors() -> Vectors {
    let all: Vectors =
        serde_json::from_str(include_str!("../fixtures/initdata_vectors.json")).unwrap();
    assert_eq!(
        all.bot_token,
        common::TEST_BOT_TOKEN,
        "bot_token mismatch: the vectors are not signed with the test state's bot token"
    );
    all
}

fn vector<'a>(all: &'a Vectors, name: &str) -> &'a Vector {
    all.vectors
        .iter()
        .find(|v| v.name == name)
        .unwrap_or_else(|| panic!("vector {name} missing from initdata_vectors.json"))
}

fn validate(all: &Vectors, v: &Vector) -> Result<InitData, InitDataError> {
    validate_init_data(&v.init_data, &all.bot_token, all.now, all.max_age_secs)
}

/// `None` when the validator's outcome is the vector's `expect` (for `ok`: also its user), else the failure line.
fn check_vector(all: &Vectors, v: &Vector) -> Option<String> {
    let got = validate(all, v);
    match (v.expect.as_str(), &got) {
        ("ok", Ok(data)) => {
            let Some(want) = &v.user else {
                return Some(format!("{}: an ok vector without a user", v.name));
            };
            let user = &data.user;
            let same = user.id.0 == want.id
                && user.first_name == want.first_name
                && user.language_code == want.language_code;
            (!same).then(|| {
                format!(
                    "{}: expected user ({}, {:?}, {:?}), got {user:?}",
                    v.name, want.id, want.first_name, want.language_code
                )
            })
        }
        ("ok", Err(e)) => Some(format!("{}: expected Ok, got Err({e:?})", v.name)),
        (want, Err(e)) if format!("{e:?}") == want => None,
        (want, _) => Some(format!("{}: expected {want}, got {got:?}", v.name)),
    }
}

fn report(failures: &[String]) {
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

fn check_named(names: &[&str]) {
    let all = vectors();
    let failures: Vec<String> = names
        .iter()
        .filter_map(|name| check_vector(&all, vector(&all, name)))
        .collect();
    report(&failures);
}

#[test]
fn initdata_valid_vector() {
    check_named(&["valid", "valid_no_language"]);
}

/// A field changed after signing is a bad hash, also when the changed initData is expired: the HMAC runs before
/// any field is read.
#[test]
fn initdata_tampered_field() {
    check_named(&["tampered_user", "tampered_auth_date", "expired_tampered"]);
}

#[test]
fn initdata_missing_hash() {
    check_named(&["missing_hash"]);
}

/// One second past the max age is expired; exactly the max age is accepted.
#[test]
fn initdata_expired() {
    check_named(&["expired", "age_at_limit"]);
}

/// 61 s ahead is refused; exactly the 60 s skew is accepted.
#[test]
fn initdata_from_future() {
    check_named(&["future", "future_within_skew"]);
}

#[test]
fn initdata_reordered_keys() {
    check_named(&["reordered"]);
}

/// The HMAC runs over decoded values: `%xx` (Cyrillic, `&`, `=`, `+`, `%`) and `+` as a space.
#[test]
fn initdata_url_encoded_values() {
    let all = vectors();
    let mut failures: Vec<String> = ["encoded", "plus_as_space"]
        .iter()
        .filter_map(|name| check_vector(&all, vector(&all, name)))
        .collect();
    // Pinned here as literals too, so a fixture that encodes and expects the same wrong text cannot pass.
    for (name, want) in [
        ("encoded", "Анна-Мария & Co = 1+1 = 100%"),
        ("plus_as_space", "Ann Lee"),
    ] {
        match validate(&all, vector(&all, name)) {
            Ok(data) if data.user.first_name == want => {}
            got => failures.push(format!("{name}: expected first_name {want:?}, got {got:?}")),
        }
    }
    report(&failures);
}

#[test]
fn initdata_duplicate_key() {
    check_named(&["duplicate_auth_date", "duplicate_hash"]);
}

/// Fields the server does not know are signed too (no whitelist); a field added after signing is a bad hash.
#[test]
fn initdata_unknown_field_included() {
    check_named(&["unknown_field", "unsigned_extra_field"]);
}

/// `signature` is part of the data-check-string: signed with it verifies, signed without it does not.
#[test]
fn initdata_signature_in_dcs() {
    check_named(&["with_signature", "signature_excluded_from_dcs"]);
}

/// Correctly signed initData whose fields are missing or have the wrong shape.
#[test]
fn initdata_signed_malformed_rejected() {
    check_named(&[
        "no_user",
        "no_auth_date",
        "auth_date_not_integer",
        "user_not_json",
        "user_without_id",
    ]);
}

#[test]
fn initdata_all_vectors_match_expectations() {
    let all = vectors();
    let mut failures = Vec::new();
    if all.vectors.len() != VECTOR_COUNT {
        failures.push(format!(
            "vector count: expected {VECTOR_COUNT}, got {}",
            all.vectors.len()
        ));
    }
    let mut names: Vec<&str> = all.vectors.iter().map(|v| v.name.as_str()).collect();
    names.sort_unstable();
    names.dedup();
    if names.len() != all.vectors.len() {
        failures.push("vector names are not unique".to_owned());
    }
    failures.extend(all.vectors.iter().filter_map(|v| check_vector(&all, v)));
    report(&failures);
}

/// The function the dev signer builds initData with: drops only `hash` (`signature` stays), sorts by key.
#[test]
fn initdata_dcs_sorts_and_drops_only_hash() {
    let pairs = [("b", "2"), ("hash", "x"), ("signature", "s"), ("a", "1")]
        .map(|(k, v)| (k.to_owned(), v.to_owned()));
    let got = data_check_string(&pairs);
    assert_eq!(got, "a=1\nb=2\nsignature=s", "data_check_string");
}
